// ================================================================
//  13-8-1: 辞書を貯める（mergeImportDictionary_）  【大B / 中13 / 小13-8-1】
//  設定シートH〜K列の取込辞書に、rows（[種類, フィールドID, 表示名, 別名のカンマ区切り] の並び）を足す
//  辞書の初期化（13-8。決まった項目）と②③反映（12-3c-6。①の辞書）から呼ぶ
//  ・辞書は貯めていくもの。今ある行・別名は絶対に消さない・変えない・並べ替えない（客が覚えさせた別名も、①に無い行もそのまま残す）
//  ・同じ項目（種類＋フィールドIDが同じ行）があれば、その行の別名（K列）の後ろに、まだ無い別名だけを足す
//    表示名（J列）は空の時だけ入れる
//  ・同じ項目が無ければ、H〜K列の一番下の行の次に、その行を足す（行が足りなければシートの下に行を足す）
//  ・①で別名を消しても②③からは消えない（貯める決まりのため）
// ================================================================
function mergeImportDictionary_(setting, rows) {
  if (!setting || !rows || rows.length === 0) return;
  if (setting.getMaxColumns() < 11) setting.insertColumnsAfter(setting.getMaxColumns(), 11 - setting.getMaxColumns());
  var lr = setting.getLastRow();
  var cur = lr >= 2 ? setting.getRange(2, 8, lr - 1, 4).getValues() : [];
  var keyIdx = {}, lastUsed = 0;   // lastUsed＝H〜K列で何か入っている一番下の行（2行目＝1）
  for (var i = 0; i < cur.length; i++) {
    var t = String(cur[i][0] || '').trim(), f = String(cur[i][1] || '').trim();
    if (t || f || String(cur[i][2] || '').trim() || String(cur[i][3] || '').trim()) lastUsed = i + 1;
    if (t && f && keyIdx[t + '\t' + f] === undefined) keyIdx[t + '\t' + f] = i;
  }
  var jCol = cur.map(function(r) { return [r[2]]; });
  var kCol = cur.map(function(r) { return [r[3]]; });
  var jChanged = false, kChanged = false, toAdd = [];
  rows.forEach(function(r) {
    var t = String(r[0] || '').trim(), f = String(r[1] || '').trim();
    if (!t || !f) return;
    var add = String(r[3] || '').split(',').map(function(a) { return a.trim(); }).filter(Boolean);
    var idx = keyIdx[t + '\t' + f];
    if (idx === undefined) {
      toAdd.push([t, f, r[2] == null ? '' : r[2], add.join(',')]);
      keyIdx[t + '\t' + f] = -1;   // 同じ項目を2回足さない
      return;
    }
    if (idx < 0) return;
    if (String(jCol[idx][0] || '').trim() === '' && String(r[2] || '').trim() !== '') { jCol[idx][0] = r[2]; jChanged = true; }
    var curStr = String(kCol[idx][0] == null ? '' : kCol[idx][0]);
    var have = curStr.split(',').map(function(a) { return a.trim(); }).filter(Boolean);
    var extra = add.filter(function(a, n) { return have.indexOf(a) === -1 && add.indexOf(a) === n; });
    if (extra.length === 0) return;
    kCol[idx][0] = curStr.trim() === '' ? extra.join(',') : curStr.replace(/,\s*$/, '') + ',' + extra.join(',');
    kChanged = true;
  });
  if (jChanged) setting.getRange(2, 10, jCol.length, 1).setValues(jCol);
  if (kChanged) setting.getRange(2, 11, kCol.length, 1).setValues(kCol);
  if (toAdd.length > 0) {
    var nr = lastUsed + 2;
    if (setting.getMaxRows() < nr + toAdd.length - 1) setting.insertRowsAfter(setting.getMaxRows(), nr + toAdd.length - 1 - setting.getMaxRows());
    setting.getRange(nr, 8, toAdd.length, 4).setValues(toAdd);
  }
}

// ================================================================
//  13-8a: 辞書エイリアス追加（addImportDictionaryAlias_）  【大B / 中13 / 小13-8a】
//  設定シートH〜K列の取込辞書で、種類（H列）と表示名（J列）が一致する行のK列（別名のカンマ区切り）に新しい別名を足す（すでにあれば何もしない）
// ================================================================
function addImportDictionaryAlias_(ss, sheetType, displayName, newAlias) {
  var setting = ss.getSheetByName('設定');
  if (!setting || setting.getLastRow() < 2) return;
  var data = setting.getRange(2, 8, setting.getLastRow() - 1, 4).getValues();
  for (var i = 0; i < data.length; i++) {
    if (String(data[i][0]).trim() !== sheetType) continue;
    if (String(data[i][2]).trim() !== displayName) continue;
    var aliases = String(data[i][3]).split(',').map(function(a) { return a.trim(); }).filter(Boolean);
    if (aliases.indexOf(newAlias) !== -1) return;
    aliases.push(newAlias);
    setting.getRange(i + 2, 11).setValue(aliases.join(','));
    return;
  }
}

// ================================================================
//  13-9: インポート用日付変換（parseImportDate_）  【大B / 中13 / 小13-9】
//  SheetJSシリアル値・ISO文字列・DateオブジェクトをDate型に変換する
//  変換不可な値はnullを返す
// ================================================================
function parseImportDate_(v) {
  if (v === null || v === undefined || v === '') return null;
  if (v instanceof Date) return isNaN(v.getTime()) ? null : v;
  var n = Number(v);
  if (!isNaN(n) && n > 40000) {
    return new Date(Math.round((n - 25569) * 86400 * 1000));
  }
  var s = String(v).trim();
  // YYYY年MM月DD日 / YYYY/MM/DD / YYYY-MM-DD
  var m1 = s.match(/^(\d{4})[年\/\-](\d{1,2})[月\/\-](\d{1,2})/);
  if (m1) return new Date(+m1[1], +m1[2] - 1, +m1[3]);
  // MM月DD日 / MM/DD（年なし→当年）
  var m2 = s.match(/^(\d{1,2})[月\/](\d{1,2})/);
  if (m2) return new Date(new Date().getFullYear(), +m2[1] - 1, +m2[2]);
  var d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}


// ================================================================
//  13-10: インポート数値変換補助（toImportNum_）  【大B / 中13 / 小13-10】
//  数値に変換できれば数値を、空・変換不可なら空文字を返す
// ================================================================
function toImportNum_(v) {
  if (v === null || v === undefined || v === '') return '';
  if (typeof v === 'number') return isNaN(v) ? '' : v;
  var s = String(v).replace(/[¥￥,，\s　]/g, '');
  var n = Number(s);
  return isNaN(n) ? '' : n;
}


// ================================================================
//  13-10a: 辞書エイリアス自動保存（saveImportAliases）  【大A / 中13 / 小13-10a】
//  手動マッピングで使われたExcel列名を設定シートの辞書に自動追記する
//  次回インポート時に同じExcelを使うと自動マッピングされるようになる
//  既に同じ内容（大文字小文字・空白無視）が登録済みの場合はスキップする
//  スプレッドシートの画面から、または管理画面（ログイン状態 token）から対象SSを決めて動く（P-5e）
// ================================================================
function saveImportAliases(sheetType, newMappings, companySsId, token) {
  useToolSs_(companySsId, token);   // 対象SSの決定と本人確認（P-5e）
  if (!newMappings || newMappings.length === 0) return;
  var ss      = getTargetSS_(companySsId);
  var setting = ss.getSheetByName('設定');
  if (!setting || setting.getLastRow() < 2) return;
  var lr   = setting.getLastRow();
  var rows = setting.getRange(2, 8, lr - 1, 4).getValues();
  for (var m = 0; m < newMappings.length; m++) {
    var nm       = newMappings[m];
    var newAlias = String(nm.alias || '').trim();
    if (!newAlias) continue;
    for (var i = 0; i < rows.length; i++) {
      if (String(rows[i][0] || '').trim() !== sheetType)  continue;
      if (String(rows[i][1] || '').trim() !== nm.fieldId) continue;
      var aliasStr = String(rows[i][3] || '').trim();
      var aliases  = aliasStr ? aliasStr.split(',').map(function(a) { return a.trim(); }) : [];
      var already  = aliases.some(function(a) {
        return a.toLowerCase().replace(/\s/g, '') === newAlias.toLowerCase().replace(/\s/g, '');
      });
      if (!already) {
        aliases.push(newAlias);
        setting.getRange(i + 2, 11, 1, 1).setValue(aliases.join(','));
      }
      break;
    }
  }
}



// ================================================================
//  14-4: 帳票発行済マーク（markDocumentIssued）  【大A / 中14 / 小14-4】
//  運行シートでIDが一致する最初の行の「発注書・指示書」列（docType=hatchu）または「車番連絡」列に、今の日時（MM/dd HH:mm の文字）を書く
//  スプレッドシートの画面から、または管理画面（ログイン状態 token）から対象SSを決めて動く（P-5e）
// ================================================================
function markDocumentIssued(rowId, docType, ssId, token) {
  useToolSs_(ssId, token);   // 対象SSの決定と本人確認（P-5e）
  if (!rowId) return;
  var ss    = ssId ? SpreadsheetApp.openById(ssId) : SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName('運行');
  if (!sheet || sheet.getLastRow() < 2) return;
  var lastCol = sheet.getLastColumn();
  var hdrs    = sheet.getRange(1, 1, 1, lastCol).getValues()[0].map(function(h){ return String(h||'').trim(); });
  var colName = (docType === 'hatchu') ? '発注書・指示書' : '車番連絡';
  var colIdx  = hdrs.indexOf(colName); // 0-based
  if (colIdx === -1) return;
  var ids = sheet.getRange(2, 1, sheet.getLastRow() - 1, 1).getValues();
  for (var i = 0; i < ids.length; i++) {
    if (String(ids[i][0]||'').trim() === rowId) {
      var issuedCell = sheet.getRange(i + 2, colIdx + 1);
      issuedCell.setNumberFormat('@');
      issuedCell.setValue(Utilities.formatDate(new Date(), 'Asia/Tokyo', 'MM/dd HH:mm'));
      ss.toast(colName + ' を発行済にしました（ID: ' + rowId + '）', '✅', 3);
      return;
    }
  }
}


// ================================================================
//  14-5: 帳票メール送信（sendDocumentEmail）  【大A / 中14 / 小14-5】
//  荷主名でマスタ（取引先）を探し、method=email ならメールアドレス宛に送って発行済（14-4）にし、指示先があれば履歴に保存（14-7i）する
//  アドレス未登録時の案内は、マスタの見出しから求めた実際の列を示す。返り値：{ok, msg}
//  メールは客の取引先宛なので、①の持ち主へのCCは付けない（12-6d-0 の noCc）
//  FAXはここを通らない（画面の FAX ボタンは印刷と同じく印刷画面を開いて 14-4 で発行日時を記録するだけ。送信は各会社のFAX機能で行う）
//  スプレッドシートの画面から、または管理画面（ログイン状態 token）から対象SSを決めて動く（P-5e）
// ================================================================
function sendDocumentEmail(docData, docType, method, token) {
  useToolSs_(docData && docData.ssId, token);   // 対象SSの決定と本人確認（P-5e）
  var ss  = docData.ssId ? SpreadsheetApp.openById(docData.ssId) : SpreadsheetApp.getActiveSpreadsheet();
  var custSheet = ss.getSheetByName('マスタ');
  if (!custSheet || custSheet.getLastRow() < 2) return { ok: false, msg: 'マスタシートが見つかりません。' };

  var cLastCol = custSheet.getLastColumn();
  var cHdrs = custSheet.getRange(1,1,1,cLastCol).getValues()[0].map(function(h){return String(h||'').trim();});
  var cData = custSheet.getRange(2,1,custSheet.getLastRow()-1,cLastCol).getValues();
  var nIdx     = cHdrs.indexOf('会社名');
  var emailIdx = cHdrs.indexOf('メールアドレス');

  var clientName = String(docData.client || '').trim();
  if (!clientName) return { ok: false, msg: '荷主名が取得できません。' };

  var custRow = null;
  for (var i = 0; i < cData.length; i++) {
    if (String(cData[i][nIdx]||'').trim() === clientName) { custRow = cData[i]; break; }
  }
  if (!custRow) return { ok: false, msg: '「' + clientName + '」がマスタに見つかりません。' };

  if (method === 'email') {
    var email = (emailIdx >= 0) ? String(custRow[emailIdx]||'').trim() : '';
    if (!email) return { ok: false, msg: 'メールアドレスが未登録です。\nマスタシートの' + (emailIdx >= 0 ? String.fromCharCode(65 + emailIdx) + '列（メールアドレス）' : '「メールアドレス」列') + 'に登録してください。' };
    var docName = (docType === 'hatchu') ? '発注書・指示書' : '車番連絡';
    var subject = docName + '【' + (docData.dateStr||'') + '】' + (docData.selfName||'');
    var body = clientName + ' 御中\n\n下記の通りご連絡申し上げます。\n\n'
      + '運行日：' + (docData.dateStr||'') + '（' + (docData.wdStr||'') + '）\n'
      + '積　地：' + (docData.pickPlace||'') + '\n'
      + '降　地：' + (docData.dropPlace||'') + '\n'
      + '車　番：' + (docData.car||'') + '\n'
      + '乗務員：' + (docData.driver||'') + '\n\n'
      + (docData.selfName||'');
    sendMail_(email, subject, body, { noCc: true });   // 客の取引先へのメールなので①の持ち主へCCしない（12-6d-0）
    markDocumentIssued(docData.id, docType, docData.ssId, token);
    if (docData.shijisaki) { try { saveShijisakiHistory_(String(docData.client||''), docData.shijisaki, ss); } catch(e) {} }
    return { ok: true, msg: email + ' に送信しました。' };
  }

  return { ok: false, msg: '不明な送信方法です。' };
}


// ================================================================
//  14-6: 指示先履歴取得（getShijisakiHistory）  【大A / 中14 / 小14-6】
//  発注書ダイアログの「📋 履歴」ボタンから google.script.run 経由で呼ばれる
//  荷主名に紐づく全件を返す（最終使用日の降順）
//  スプレッドシートの画面から、または管理画面（ログイン状態 token）から対象SSを決めて動く（P-5e）
// ================================================================
function getShijisakiHistory(clientName, ssId, token) {
  useToolSs_(ssId, token);   // 対象SSの決定と本人確認（P-5e）
  if (!ssId) return [];
  var ss;
  try { ss = SpreadsheetApp.openById(ssId); } catch(e) { return []; }
  if (!ss) return [];
  var sh = ss.getSheetByName('指示先履歴');
  if (!sh || sh.getLastRow() < 2) return [];
  var data = sh.getRange(2, 1, sh.getLastRow() - 1, 6).getValues();
  var results = [];
  data.forEach(function(r) {
    if (String(r[0]||'').trim() !== String(clientName||'').trim()) return;
    var lastUsed = '';
    if (r[5]) {
      try { lastUsed = Utilities.formatDate(r[5] instanceof Date ? r[5] : new Date(r[5]), 'Asia/Tokyo', 'yyyy/MM/dd'); } catch(ex) {}
    }
    results.push({ company: String(r[1]||''), tel: String(r[2]||''), person: String(r[3]||''), addr: String(r[4]||''), lastUsed: lastUsed });
  });
  results.sort(function(a, b) { return (b.lastUsed||'').localeCompare(a.lastUsed||''); });
  return results;
}

// ================================================================
//  14-7: 指示先履歴保存・公開ラッパー（saveShijisakiHistory）  【大A / 中14 / 小14-7】
//  印刷時など sendDocumentEmail を経由しない場合に HTML から直接呼ばれる
//  スプレッドシートの画面から、または管理画面（ログイン状態 token）から対象SSを決めて動く（P-5e）
// ================================================================
function saveShijisakiHistory(clientName, shijisaki, ssId, token) {
  useToolSs_(ssId, token);   // 対象SSの決定と本人確認（P-5e）
  if (!ssId) return;
  var ss;
  try { ss = SpreadsheetApp.openById(ssId); } catch(e) { return; }
  if (!ss) return;
  saveShijisakiHistory_(clientName, shijisaki, ss);
}

// ================================================================
//  14-7i: 指示先履歴保存・内部実装（saveShijisakiHistory_）  【大B / 中14 / 小14-7i】
//  重複チェック: 荷主名＋会社名＋電話＋担当者＋住所が同一なら最終使用日を更新のみ
// ================================================================
function saveShijisakiHistory_(clientName, shijiData, ss) {
  if (!ss) ss = SpreadsheetApp.getActiveSpreadsheet();
  var company = String(shijiData.company||'').trim();
  var tel     = String(shijiData.tel    ||'').trim();
  var person  = String(shijiData.person ||'').trim();
  var addr    = String(shijiData.addr   ||'').trim();
  if (!company && !tel && !person && !addr) return;
  var sh = ss.getSheetByName('指示先履歴');
  if (!sh) {
    sh = ss.insertSheet('指示先履歴');
    sh.getRange(1, 1, 1, 6).setValues([['荷主名', '指示先会社名', '電話番号', '担当者名', '住所', '最終使用日']]);
    sh.hideSheet();
  }
  var cName = String(clientName||'').trim();
  var now = new Date();
  if (sh.getLastRow() >= 2) {
    var rows = sh.getRange(2, 1, sh.getLastRow() - 1, 5).getValues();
    for (var i = 0; i < rows.length; i++) {
      if (String(rows[i][0]||'').trim() === cName &&
          String(rows[i][1]||'').trim() === company &&
          String(rows[i][2]||'').trim() === tel &&
          String(rows[i][3]||'').trim() === person &&
          String(rows[i][4]||'').trim() === addr) {
        sh.getRange(i + 2, 6).setValue(now);
        return;
      }
    }
  }
  sh.appendRow([cName, company, tel, person, addr, now]);
}


// ================================================================
//  14-8: 行ID別指示先取得（getShijisakiByRowId）  【大A / 中14 / 小14-8】
//  発注書ダイアログを開いた時にそのIDの保存済み指示先情報を返す
//  スプレッドシートの画面から、または管理画面（ログイン状態 token）から対象SSを決めて動く（P-5e）
// ================================================================
function getShijisakiByRowId(rowId, ssId, token) {
  useToolSs_(ssId, token);   // 対象SSの決定と本人確認（P-5e）
  var ss = ssId ? SpreadsheetApp.openById(ssId) : SpreadsheetApp.getActiveSpreadsheet();
  var sh = ss.getSheetByName('指示先ID別');
  if (!sh || sh.getLastRow() < 2) return null;
  var data = sh.getRange(2, 1, sh.getLastRow() - 1, 5).getValues();
  var rid = String(rowId||'').trim();
  for (var i = 0; i < data.length; i++) {
    if (String(data[i][0]||'').trim() === rid) {
      return { company: String(data[i][1]||''), tel: String(data[i][2]||''), person: String(data[i][3]||''), addr: String(data[i][4]||'') };
    }
  }
  return null;
}

// ================================================================
//  14-9: 行ID別指示先保存（saveShijisakiByRowId）  【大A / 中14 / 小14-9】
//  入力中にリアルタイム保存（0.8秒デバウンス）＋指示先履歴にも反映
//  スプレッドシートの画面から、または管理画面（ログイン状態 token）から対象SSを決めて動く（P-5e）
// ================================================================
function saveShijisakiByRowId(rowId, shijiData, clientName, ssId, token) {
  useToolSs_(ssId, token);   // 対象SSの決定と本人確認（P-5e）
  var ss = ssId ? SpreadsheetApp.openById(ssId) : SpreadsheetApp.getActiveSpreadsheet();
  var company = String(shijiData.company||'').trim();
  var tel     = String(shijiData.tel    ||'').trim();
  var person  = String(shijiData.person ||'').trim();
  var addr    = String(shijiData.addr   ||'').trim();
  var rid     = String(rowId||'').trim();

  var sh = ss.getSheetByName('指示先ID別');
  if (!sh) {
    sh = ss.insertSheet('指示先ID別');
    sh.getRange(1, 1, 1, 5).setValues([['行ID', '指示先会社名', '電話番号', '担当者名', '住所']]);
    sh.hideSheet();
  }
  var updated = false;
  if (sh.getLastRow() >= 2) {
    var rows = sh.getRange(2, 1, sh.getLastRow() - 1, 1).getValues();
    for (var i = 0; i < rows.length; i++) {
      if (String(rows[i][0]||'').trim() === rid) {
        sh.getRange(i + 2, 2, 1, 4).setValues([[company, tel, person, addr]]);
        updated = true;
        break;
      }
    }
  }
  if (!updated) sh.appendRow([rid, company, tel, person, addr]);

  if (company || tel || person || addr) {
    saveShijisakiHistory_(String(clientName||''), shijiData, ss);
  }
}


// ================================================================
//  14-10: 指示先履歴削除（deleteShijisakiHistory）  【大A / 中14 / 小14-10】
//  履歴モーダルの「削除」ボタンから google.script.run 経由で呼ばれる
//  スプレッドシートの画面から、または管理画面（ログイン状態 token）から対象SSを決めて動く（P-5e）
// ================================================================
function deleteShijisakiHistory(clientName, company, tel, person, addr, ssId, token) {
  useToolSs_(ssId, token);   // 対象SSの決定と本人確認（P-5e）
  var ss = ssId ? SpreadsheetApp.openById(ssId) : SpreadsheetApp.getActiveSpreadsheet();
  var sh = ss.getSheetByName('指示先履歴');
  if (!sh || sh.getLastRow() < 2) return;
  var cName = String(clientName||'').trim();
  var cComp = String(company    ||'').trim();
  var cTel  = String(tel        ||'').trim();
  var cPer  = String(person     ||'').trim();
  var cAddr = String(addr       ||'').trim();
  var rows = sh.getRange(2, 1, sh.getLastRow() - 1, 5).getValues();
  for (var i = rows.length - 1; i >= 0; i--) {
    if (String(rows[i][0]||'').trim() === cName &&
        String(rows[i][1]||'').trim() === cComp &&
        String(rows[i][2]||'').trim() === cTel  &&
        String(rows[i][3]||'').trim() === cPer  &&
        String(rows[i][4]||'').trim() === cAddr) {
      sh.deleteRow(i + 2);
      return;
    }
  }
}


